WITH cleaned AS (SELECT *, CAST(amount AS INT) AS amount_int, COALESCE(method, 'OTHER') AS resolved_method FROM payments WHERE method IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT method, AVG(amount_int) FILTER (WHERE method = 'promptpay') AS promptpay_avg_amount_int, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE method = 'card') AS card_rows, SUM(CASE WHEN method = 'paypal' THEN session_start_flag ELSE 0 END) AS paypal_session_start_flag, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, COUNT(*) FILTER (WHERE status = 'SUCCESS') AS success_rows FROM sessions_payments GROUP BY method ORDER BY method DESC
